INSERT INTO `case_studies` (`id`, `slug`, `title`, `subtitle`, `result`, `thumb`, `category`, `challenge`, `approach`, `results`, `testimonial`, `created_at`, `updated_at`) VALUES
  (21, 'nutrivend-uk', 'Nutrivend UK', 'B2B Market Validation & Lead Generation', '45 Leads • 71% Untapped Market', 'https://images.unsplash.com/photo-1534438327276-14e5300c3a48?auto=format&fit=crop&q=80&w=1200', 'Meta Lead Gen', 'Nutrivend UK wanted to expand into the enterprise fitness vending space but had no data on whether the market was worth chasing — every prior outreach effort had been generic cold email with no signal on real demand.', '["Built a rigorous B2B market validation framework instead of running blind outreach", "Ran targeted Meta lead-gen campaigns aimed squarely at enterprise fitness facility decision-makers", "Instrumented every lead with qualification data to separate genuine demand from noise"]', '[{"label": "Qualified leads", "value": "45 in 7 days"}, {"label": "Market discovery", "value": "71% untapped enterprise demand"}, {"label": "Cost per qualified lead", "value": "62% below benchmark"}]', '{"quote": "Qala Labs didn''t just run ads; they engineered a rigorous B2B market validation framework. Generating 45 qualified enterprise fitness leads in just 7 days with a 71% untapped market discovery proved our new expansion thesis beyond doubt.", "name": "Marcus Vance", "role": "Managing Director, Nutrivend UK"}', '2026-09-24 16:37:32', '2026-09-24 16:37:32'),
  (22, 'trotr-spain-pivot', 'Trotr: Spain Pivot', 'High-Ticket Travel Funnel & Founder Narrative', '28x ROAS • ₹14L Revenue', '/assets/qala/trotr-featured.jpeg', 'Founder Storytelling', 'Trotr had zero paying customers for its high-ticket Spain trip despite running conventional travel ads — the offer looked like every other travel package in the feed and never earned trust at a high price point.', '["Rewrote the entire funnel narrative around founder-led storytelling instead of generic destination marketing", "Rebuilt creative and copy to sell the trip on trust and specificity rather than discounting", "Optimized the funnel end-to-end from ad hook through checkout for a high-ticket buying decision"]', '[{"label": "ROAS", "value": "28x"}, {"label": "Revenue generated", "value": "\\u20b914 Lakhs"}, {"label": "Conversion cycle", "value": "Reduced from 21 days to 72 hours"}]', '{"quote": "We had zero paying customers for our high-ticket Spain trip despite running traditional travel ads. Qala Labs stepped in, rewrote our narrative with founder-led storytelling, and generated \\u20b914 Lakhs in revenue at a staggering 28x ROAS.", "name": "Siddharth Roy", "role": "Co-Founder & CEO, Trotr"}', '2026-09-24 16:37:32', '2026-09-24 16:37:32'),
  (23, 'mizuno-india', 'Mizuno India', 'Performance Apparel Brand & D2C Growth Engine', '3.8x Blended ROAS • 400% D2C Growth', 'https://images.unsplash.com/photo-1517838277536-f5f99be501cd?auto=format&fit=crop&q=80&w=1200', 'Performance Apparel', 'Mizuno held undisputed global acclaim among professional athletes, but its Indian digital footprint lagged behind legacy competitors with generic catalog ads failing to convey Japanese precision engineering.', '["Rebuilt the digital visual identity highlighting technical shoe anatomy and biomechanics", "Structured high-intent Google Search and Meta CAPI funnels targeting elite runners and badminton pros", "Introduced dynamic fit-finder workflows and athlete endorsement storytelling"]', '[{"label": "Blended ROAS", "value": "3.8x across channels"}, {"label": "D2C sales growth", "value": "+400% YoY"}, {"label": "Return rate reduction", "value": "28% drop via fit-finder"}]', '{"quote": "Qala Labs translated Mizuno\\u2019s legacy of Japanese precision into a modern digital conversion engine. They grew our direct-to-consumer channel by 400% while elevating our brand standing.", "name": "Rajeev Singhania", "role": "Commercial Director, Mizuno India"}', '2026-09-24 16:37:32', '2026-09-24 16:37:32'),
  (24, 'chrono-seconds', 'Chrono Seconds', 'Luxury Pre-Owned Horology Marketplace', '₹4.2Cr+ Pipeline • High-Net-Worth Buyers', 'https://images.unsplash.com/photo-1522335789203-aabd1fc54bc9?auto=format&fit=crop&q=80&w=1200', 'Luxury E-commerce', 'Chrono Seconds operates in pre-owned luxury horology, a category where trust and provenance matter more than price — generic e-commerce marketing playbooks fail to reach genuinely high-net-worth buyers.', '["Built a luxury-positioned marketplace experience calibrated to serious watch collectors", "Targeted acquisition toward verified high-net-worth buyer segments rather than broad reach", "Prioritized provenance, archival documentation, and vault authentication signals throughout the buying journey"]', '[{"label": "Pipeline generated", "value": "\\u20b94.2Cr+"}, {"label": "Average order value", "value": "\\u20b98.4 Lakhs"}, {"label": "Buyer segment", "value": "Verified HNW collectors"}]', '{"quote": "Selling rare Patek Philippe and Rolex references online requires bulletproof credibility. Qala Labs crafted a digital provenance experience that gave collectors complete confidence, driving over \\u20b94.2Cr in verified pipeline.", "name": "Rohan Kapoor", "role": "Founder & Horological Curator, Chrono Seconds"}', '2026-09-24 16:37:32', '2026-09-24 16:37:32'),
  (25, 'gaffar-india', 'Gaffar India', 'Market Stall to Digital Multi-Vendor Marketplace', '6 Asset Packages • 28-Day Delivery', '/assets/qala/gaffar-new-logo.webp', 'Brand Identity & Web', 'Gaffar India carried decades of local market trust as a physical stall business, but had no digital identity or infrastructure to bring that trust online as a multi-vendor marketplace.', '["Rebuilt the brand identity to balance Gaffar Market heritage with modern digital usability", "Shipped 6 complete asset packages covering brand, web, and marketplace UI", "Delivered the full rebrand and platform in a rapid 28-day sprint"]', '[{"label": "Asset packages delivered", "value": "6"}, {"label": "Delivery timeline", "value": "28 days"}, {"label": "Merchant onboarding", "value": "120+ vendors live on day one"}]', '{"quote": "Qala Labs helped us turn a local market legacy into a modern marketplace identity. Their strategy balanced our Gaffar Market roots with digital usability \\u2014 our sellers felt seen, buyers trusted the site more, and the brand is finally ready to scale.", "name": "Akaash Maskeen", "role": "Founder & CEO, Gaffar India"}', '2026-09-24 16:37:32', '2026-09-24 16:37:32'),
  (26, 'capital-keys', 'Capital Keys', 'Real Estate Proptech Platform & CRM Engine', '64.7% Conversion • 17+ Leads', 'https://images.unsplash.com/photo-1486324803388-c52646db42da?auto=format&fit=crop&q=80&w=1200', 'Web App & CRM', 'Capital Keys needed a real estate platform that could convert serious property inquiries into qualified leads without losing buyers to a clunky web experience.', '["Designed and built a proptech web app with an integrated CRM for lead capture", "Optimized the inquiry-to-lead flow to remove friction at every step", "Built the platform to serve as the single source of truth for the sales pipeline"]', '[{"label": "Inquiry-to-lead conversion", "value": "64.7%"}, {"label": "Qualified leads", "value": "17+ in initial rollout"}, {"label": "Agent response latency", "value": "< 90 seconds via webhook"}]', NULL, '2026-09-24 16:37:32', '2026-09-24 16:37:32'),
  (27, 'marksops-autonomous-swarm', 'MarksOps Autonomous Operations Swarm', 'Enterprise AI Agent Orchestration', '94% Less Manual Drag • 24/7 Autonomy', 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?auto=format&fit=crop&q=80&w=1200', 'AI & Automation', 'Internal marketing, CRM lead scoring, and financial reconciliation required hours of daily manual spreadsheet reconciliation and repetitive copy-pasting between disparate software tools.', '["Engineered an autonomous multi-agent swarm architecture with persistent state checkpointing", "Integrated real-time webhooks connecting advertising spend, bank feeds, and CRM statuses", "Deployed self-correcting error recovery routines allowing swarms to operate continuously without human intervention"]', '[{"label": "Manual task reduction", "value": "94% automated"}, {"label": "Processing latency", "value": "< 1.4 seconds per event"}, {"label": "Weekly hours saved", "value": "160+ team hours"}]', '{"quote": "MarksOps proved that AI agents are no longer experimental prototypes. They run our operational backbone 24/7 with zero hallucinations and complete financial auditability.", "name": "Aashirwad Sharma", "role": "Founder & Head of Systems, Qala Labs"}', '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
  (28, 'amazon-ads-scaling', 'Amazon Ads Scaling', 'D2C Advertising Engine & Algorithmic Bidding', '11.2x ROAS • 47% Lower ACOS', '/assets/qala/amazon-ads-hero.webp', 'Amazon Performance', 'A D2C brand selling on Amazon was spending aggressively on ads but watching ACOS creep upward without a proportional gain in scale.', '["Rebuilt the Amazon advertising account structure around a performance-first bidding architecture", "Systematically cut wasted spend while reallocating budget toward proven high-ROAS placements", "Layered in continuous creative and keyword testing to keep performance compounding"]', '[{"label": "ROAS", "value": "11.2x"}, {"label": "ACOS reduction", "value": "47% lower"}, {"label": "Organic rank boost", "value": "Top 3 for primary search terms"}]', NULL, '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
  (29, 'kashmiri-sound-movement', 'The Kashmiri Sound Movement', 'Mystic Studio 8 Label Launch & Organic Reach', '3.4M+ Views • Zero Ad Spend', '/assets/qala/kashmir-street-musician.webp', 'Cultural Movement', 'Mystic Studio 8 needed to launch a new music label rooted in Kashmiri sound and street culture without a paid media budget to manufacture reach.', '["Built a cultural movement narrative around authentic Kashmiri street musicians rather than a conventional label launch", "Prioritized organic distribution and shareability over paid amplification", "Let the story and the music carry the launch rather than manufactured hype"]', '[{"label": "Views generated", "value": "3.4M+"}, {"label": "Ad spend", "value": "\\u20b90 (fully organic)"}, {"label": "Streaming saves", "value": "42,000+ Spotify saves"}]', NULL, '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
  (30, 'd2c-bnpl-strategy', 'D2C BNPL Strategy', 'Payment Architecture Optimization & AOV Expansion', '15-30% Conversion Uplift', '/assets/qala/bnpl-featured.webp', 'Growth Architecture', 'A D2C brand was losing checkout conversions to price hesitation at the final step, with no flexible payment options to bridge the gap for hesitant buyers.', '["Audited the checkout flow to isolate where price hesitation was costing conversions", "Introduced and optimized Buy-Now-Pay-Later placement across the purchase funnel", "Tuned messaging around the new payment architecture to normalize its use at checkout"]', '[{"label": "Conversion uplift", "value": "15\\u201330%"}, {"label": "Cart abandonment drop", "value": "22% reduction"}, {"label": "Average order value", "value": "+18% increase"}]', NULL, '2026-09-24 16:37:33', '2026-09-24 16:37:33');
UNLOCK TABLES;

