  (33, 'wwf-india-featured', 'wwf-ai-creative-studio', 'WWF India: AI Ad Creatives', 'WWF India', 'AI Creative', '2025', 'https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&q=80&w=1200', 'Generative AI creative pipeline trained on conservation guidelines, delivering wildlife campaign assets at 80% lower production cost.', '80% Lower Production Cost • 50+ Assets/Wk', '["Bespoke LoRA Model Fine-Tuning", "ComfyUI Node-Based Multi-Format Generation", "Aspect Ratio Batch Export Pipeline (9:16, 1:1, 16:9)", "Brand Guideline Automated Enforcement Guardrails"]', '["ComfyUI", "Flux", "PyTorch", "Next.js", "Python", "Tailwind"]', NULL, NULL, 1, '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
  (34, 'capital-keys-featured', 'capital-keys-real-estate-platform', 'Capital Keys: Real Estate Platform', 'Capital Keys', 'Web Development', '2025', 'https://images.unsplash.com/photo-1512917774080-9991f1c4c750?auto=format&fit=crop&q=80&w=1200', 'High-converting luxury proptech web platform featuring interactive property map filters, buyer registration funnels, and real-time CRM webhooks.', '17+ Leads • 64.7% Conversion', '["Custom React Proptech Architecture", "Interactive Map & Property Tour Hub", "Real-Time Broker CRM Webhook Engine", "Instant Lead Qualification Funnel"]', '["React", "Node.js", "PostgreSQL", "Twilio API", "SendGrid"]', NULL, 'capital-keys', 1, '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
  (35, 'amazon-ads-featured', 'amazon-ads-scaling', 'Amazon Ads: Performance Scaling', 'Amazon Brand Ecosystem', 'Performance Marketing', '2025', '/assets/qala/amazon-ads-hero.webp', 'Strategic restructuring of Amazon Sponsored Products and Brand placements, cutting wasted spend and maximizing conversion share.', '11.2x ROAS • ₹2.7L Sales', '["Sponsored Products & Brand Store Restructuring", "Algorithmic Dayparting & Bid Management", "Negative Keyword Harvesting Routines", "ACOS Leak Elimination Architecture"]', '["Amazon Advertising Console", "Helium 10", "Dataflow", "BigQuery"]', NULL, 'amazon-ads-scaling', 1, '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
  (36, 'streetplayr-featured', 'streetplayr-storefront', 'StreetplayR: Brand, UX & Storefront', 'playR Streetwear', 'Web Development', '2025', '/assets/qala/streetplayr/hero.jpg', 'Custom e-commerce build and brand system for playR’s urban streetwear division, optimized for mobile conversion velocity and drop culture.', 'Brand System + Commerce Build', '["Headless Shopify Plus Front-End Architecture", "Drop-Countdown Notification Modules", "Mobile-First Cart Drawer & Fast Checkout Flow", "Streetwear Design System & Typography Pack"]', '["Shopify Plus", "React", "Liquid", "Tailwind CSS", "Figma"]', NULL, NULL, 1, '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
  (37, 'instagram-ugc-featured', 'instagram-ugc-lifestyle', 'Instagram UGC: Style Meets Real Life', 'D2C Apparel & Lifestyle Brands', 'Content Creation', '2025', '/assets/qala/csk-ugc-hero.webp', 'Relatable creator-led short-form content designed to bypass ad blindness and convert organic social scrollers into first-time buyers.', 'Relatability Converts Better', '["Creator Casting & Briefing Protocols", "High-Conversion Hook Scripting", "9:16 Vertical Video Production & Color Grading", "Meta Whitelisting & Dark Post Orchestration"]', '["CapCut Pro", "Premiere Pro", "Meta Ads Manager", "Figma"]', NULL, NULL, 1, '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
  (38, 'csk-influencer-featured', 'playr-real-fans-content', 'playR: Real Fans, Real Roar', 'playR Merchandise (Official IPL Merchandise Partner)', 'Content Creation', '2025', 'https://images.unsplash.com/photo-1552667466-07d71e725e34?auto=format&fit=crop&q=80&w=1200', 'Viral fan loyalty campaigns, matchday content, and official team merchandise kits engineered for playR x Chennai Super Kings Merch for IPL 2025 and 7 other IPL franchises.', 'Viral Fandom Momentum • 12,000+ Orders', '["Franchise Technical Design Packs (Apparel & Accessories)", "Matchday Social Fandom Video Challenges", "High-Concurrency Matchday Shopify Plus Architecture", "Official Chennai Super Kings Fan Merchandise Packaging"]', '["Shopify Plus", "Figma", "Liquid", "React", "Meta CAPI"]', NULL, NULL, 1, '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
  (39, 'mizuno-india-featured', 'mizuno-india-launch-production', 'Mizuno India: Launch Campaign', 'Mizuno India', 'Production & Shoots', '2025', 'https://images.unsplash.com/photo-1626224583764-f87db24ac4ea?auto=format&fit=crop&q=80&w=1200', 'Commercial multi-day production shoot capturing Mizuno’s elite running footwear and apparel in dynamic athletic motion across track and turf.', '2-Day Shoot • 5 Content Themes', '["Full On-Location Commercial Shoot Direction", "Athlete Action Capture & Slow-Mo Video Packs", "High-Res Commercial Hero Banners for D2C Store", "Social Cutdowns & Paid Ad Performance Variants"]', '["Sony FX6 Cinema", "DaVinci Resolve", "Capture One", "Photoshop"]', NULL, 'mizuno-india', 1, '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
  (40, 'hi-astro-featured', 'hi-astro-ai-character-videos', 'Hi Astro: AI Character Videos', 'Hi Astro Media', 'AI Creative', '2025', 'https://images.unsplash.com/photo-1677442136019-21780ecad995?auto=format&fit=crop&q=80&w=1200', 'Automated synthetic media pipeline generating 48 hyper-realistic AI character videos in 9:16 vertical format with automated lip-sync.', '48 Videos • 9:16 Vertical', '["Synthetic AI Persona Character Rigging", "Automated Script Generation & Voice Synthesis", "Dynamic Lip-Sync & Micro-Expression Alignment", "Batch Video Rendering & Export Pipeline"]', '["ElevenLabs", "ComfyUI", "HeyGen API", "Python", "FFmpeg"]', NULL, NULL, 1, '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
  (41, 'billu-campaign-featured', 'billu-salon-social-content', 'Billu: Salon-at-Home Content', 'Billu Care', 'Content Creation', '2025', 'https://images.unsplash.com/photo-1560066984-138dadb4c035?auto=format&fit=crop&q=80&w=1200', 'Monthly creator program producing 15 native beauty and salon-at-home demonstration videos highlighting trust, hygiene, and convenience.', '15 Posts/Month • Creator-Led', '["Regional Creator Onboarding & Storyboard Briefs", "Hygiene Verification Narrative Framework", "Call-To-Action Booking App Link Embeds", "Monthly Retargeting Ad Refresh Batches"]', '["Meta Creator Studio", "CapCut Pro", "Canva Enterprise", "Airtable"]', NULL, NULL, 0, '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
  (42, 'airtel-business-featured', 'airtel-business-exhibition', 'Airtel Business: Exhibition Coverage', 'Airtel Business', 'Production & Shoots', '2024', 'https://images.unsplash.com/photo-1540575467063-178a50c2df87?auto=format&fit=crop&q=80&w=1200', 'High-impact enterprise video coverage capturing Airtel’s flagship B2B technology exhibition, keynote demos, and executive partner interactions.', 'Enterprise B2B Launch Coverage', '["Multi-Cam On-Site Event Video Production", "Executive Leadership Soundbites & Micro-Interviews", "Same-Day Social Highlight Teasers", "Post-Event Enterprise Recap Film for Key Accounts"]', '["Canon Cinema EOS", "DJI Ronin", "DaVinci Resolve", "Premiere Pro"]', NULL, NULL, 0, '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
  (43, 'airborne-aviation-featured', 'airborne-aviation-academy', 'Airborne Aviation: Pilot Academy Website', 'Airborne Aviation Academy', 'Web Development', '2025', '/portfolio/airborne-aviation/hero.jpg', 'Complete digital academy platform featuring commercial pilot training course catalogs, alumni airline route maps, and admission inquiry flows.', 'Course Catalog + Alumni Route Map', '["Bespoke Aviation Training Website UI/UX", "Interactive Flight Hours & Fleet Explorer", "Admission Screening Application Workflow", "Automated Counselor CRM Routing"]', '["Next.js", "React", "Tailwind CSS", "Framer Motion", "Vercel"]', NULL, NULL, 1, '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
  (44, 'gaffar-india-featured', 'gaffar-india-marketplace', 'Gaffar India: Wholesale & Retail Marketplace', 'Gaffar India', 'Web Development', '2025', '/portfolio/gaffar-india/hero-thumb.jpg', 'Multi-vendor electronics marketplace bringing 120+ merchants and 1,000+ SKUs online with fast merchant payouts and consumer counterfeit protections.', 'Multi-Vendor Marketplace • 1,000+ SKUs', '["Multi-Vendor Architecture & Merchant Onboarding Hub", "1,000+ Electronics SKU Catalog Database", "Automated Merchant Escrow & Settlement Ledger", "Mobile-Optimized Fast Checkout Experience"]', '["Next.js", "PostgreSQL", "Node.js", "Tailwind CSS", "Razorpay"]', NULL, 'gaffar-india', 1, '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
  (45, 'shakti-bhog-featured', 'shakti-bhog-ugc-content', 'Shakti Bhog: Recipe-Led UGC Content', 'Shakti Bhog Foods', 'Content Creation', '2024', 'https://images.unsplash.com/photo-1590301157890-4810ed352733?auto=format&fit=crop&q=80&w=1200', 'Authentic culinary recipe reels spotlighting staple wheat, flour, and grains in everyday household meals, driving viral organic engagement.', 'Creator-Led Recipe Reel', '["Culinary Creator Cooking Series & Food Styling", "Traditional Recipe Video Directing & Editing", "Nutritional Fact Graphic Overlays", "Festive Campaign Organic Social Calendars"]', '["Premiere Pro", "After Effects", "Instagram Reels", "YouTube Shorts"]', NULL, NULL, 0, '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
  (46, 'world-pickleball-league-featured', 'world-pickleball-league', 'World Pickleball League Official Apparel & Brand System', 'World Pickleball League (CSC & Bharat Jammers)', 'Brand Systems', '2025', '/assets/qala/pickleball/csc-banner.png', 'Complete pro tournament apparel identity, team kits, and performance fan merchandise system for the premier international pickleball circuit.', 'Pro-Tour Apparel & Merch Identity', '["Pro-Tour Team Kits & Player Performance Jerseys", "Court-Side Event Merch & Fan Apparel Line", "Custom Typography & Team Badging System", "Manufacturing Tech Packs & Spec Sheets"]', '["Figma", "Illustrator", "Apparel Tech Packs", "Shopify Plus"]', NULL, NULL, 1, '2026-09-24 16:37:33', '2026-09-24 16:37:33'),
