LOCK TABLES `services` WRITE;
INSERT INTO `services` (`id`, `slug`, `name`, `track`, `tagline`, `description`, `deliverables`, `agents`, `proof`, `created_at`, `updated_at`) VALUES
  (1, 'ai-automation', 'AI Automation', 'AI', 'Multi-agent systems that run marketing, sales, ops, and finance as one workflow.', 'We don''t bolt AI onto your stack — we build the agents ourselves. MarksOps, our in-house multi-agent operations platform, unifies a LangGraph agent engine with a FastAPI backend so Marketing, Sales, Operations, and Finance share one native data layer instead of six disconnected SaaS tools. On top of it runs a deployed ops-automation layer that ingests real vendor emails, CRM leads, and marketplace listings and turns them into staged, human-approved actions — never silent auto-execution.', '["CRM lead intake & scoring agents with a 24-hour SLA-backed follow-up loop", "Finance-bill ingestion (Amazon VC, Meta/Google Ads, logistics, SaaS renewals) parsed and staged as draft entries \\u2014 zero auto-posting, every write needs human approval", "Marketplace price-discrepancy crawler and multichannel inventory sync (Unicommerce)", "Post-purchase logistics tracking, NDR handling, and payment reconciliation agents (Shiprocket, gateway feeds)", "AI ad-creative generation that cut cost 80% and produced 50+ on-brand creatives/week for WWF India"]', '[{"slug": "financial-reconciliation-agent", "name": "Financial Reconciliation Agent", "desc": "Matches payment-gateway settlements against orders and bank feeds automatically, flags mismatches for human review \\u2014 never auto-posts."}, {"slug": "finance-bills-agent", "name": "Finance Bills Agent", "desc": "Reads incoming vendor emails (Amazon VC, Meta/Google Ads, logistics, SaaS renewals), extracts and classifies spend, stages draft entries in Odoo ERP."}, {"slug": "ai-voice-receptionist", "name": "AI Voice Agent / Receptionist", "desc": "RAG-grounded voice agent that answers, qualifies, and routes calls 24/7, grounded in our own knowledge base."}, {"slug": "crm-leads-agent", "name": "CRM Leads Agent", "desc": "Scores inbound leads and enforces a 24-hour SLA-backed follow-up loop so nothing goes cold."}, {"slug": "marketplace-crawler", "name": "Marketplace Crawler", "desc": "Watches competitor and marketplace listings for price discrepancies and alerts the team in real time."}, {"slug": "inventory-sync-agent", "name": "Inventory Sync Agent", "desc": "Keeps stock levels consistent across channels via Unicommerce, so nothing oversells."}, {"slug": "logistics-ndr-agent", "name": "Logistics & NDR Agent", "desc": "Tracks post-purchase shipments end to end (Shiprocket) and manages non-delivery-report resolution automatically."}, {"slug": "tally-connector-agent", "name": "Tally Connector Agent", "desc": "Syncs approved financial entries into Tally Prime via a native XML connector."}, {"slug": "customer-support-agent", "name": "Customer Support Agent", "desc": "Handles omnichannel support conversations, escalating only what a human genuinely needs to see."}]', '[{"type": "product", "slug": "marksops", "label": "MarksOps \\u2014 the platform these agents run on"}]', '2026-09-24 16:37:20', '2026-09-24 16:37:20'),
  (2, 'ai-voice-agents', 'AI Voice Agents', 'AI', 'A RAG-grounded voice agent that answers, qualifies, and routes calls 24/7.', 'Our AI Receptionist is a voice agent built on retrieval-augmented generation — it answers calls grounded in your own knowledge base, not a generic script. It qualifies callers, answers common questions correctly the first time, and routes anything it can''t resolve to the right human, so no lead sits in a missed-call log overnight.', '["RAG pipeline grounded in your product docs, FAQs, and pricing \\u2014 no hallucinated answers", "24/7 call answering, qualification, and routing to the right team member", "Booking and follow-up capture wired straight into your CRM/lead pipeline", "Call transcripts and structured summaries for every conversation"]', NULL, '[{"type": "product", "slug": "ai-receptionist", "label": "AI Receptionist \\u2014 the product itself"}]', '2026-09-24 16:37:20', '2026-09-24 16:37:20'),
  (3, 'branding', 'Branding', 'Design', 'Identity systems built for brands making the leap from stall to storefront to scale.', 'Branding work at Qala Labs is judged by one thing: does it convert once it ships. We''ve taken a market-stall business to a full digital marketplace identity, launched an independent music label from zero, and built merchandise systems across 8 IPL franchises — always shipped as a real, usable asset kit, not a moodboard.', '["Gaffar India: market-stall brand rebuilt into a full digital marketplace identity \\u2014 6 asset packages, 28-day delivery", "The Kashmiri Sound Movement: Mystic Studio 8 label launch \\u2014 3.4M+ views, zero ad spend, organic-only", "playR: 8 IPL franchise merchandise identity systems, \\u20b92.5Cr+ merchandise revenue", "Brand guideline kits, logo systems, and packaging design ready for production"]', NULL, '[{"type": "case-study", "slug": "gaffar-india", "label": "Gaffar India \\u2014 market stall to digital marketplace"}, {"type": "case-study", "slug": "kashmiri-sound-movement", "label": "The Kashmiri Sound Movement \\u2014 label launch"}, {"type": "case-study", "slug": "chrono-seconds", "label": "Chrono Seconds \\u2014 luxury provenance & marketplace"}]', '2026-09-24 16:37:20', '2026-09-24 16:37:20'),
  (4, 'ui-ux-design', 'UI/UX Design', 'Design', 'Interfaces designed around one metric: does the user complete the task.', 'We design UI/UX for the products we then build — real estate portals, CRM dashboards, multi-vendor marketplaces — so the design has to survive contact with real workflows and real data, not just a Figma prototype. Capital Keys is the clearest proof: a proptech CRM/web-app interface that converted at 64.7% and generated 17+ qualified leads.', '["Capital Keys: real estate proptech web-app UI/UX \\u2014 64.7% conversion, 17+ leads", "Marketplace UI/UX systems (Gaffar India multi-vendor storefront)", "CRM/dashboard interface design (MarksOps, Q Manager Work OS)", "Design-to-dev handoff as production-ready component specs, not static mockups"]', NULL, '[{"type": "case-study", "slug": "capital-keys", "label": "Capital Keys \\u2014 proptech web app & CRM"}, {"type": "case-study", "slug": "gaffar-india", "label": "Gaffar India \\u2014 marketplace UI/UX"}, {"type": "product", "slug": "q-manager", "label": "Q Manager \\u2014 Work OS dashboard"}]', '2026-09-24 16:37:20', '2026-09-24 16:37:20'),
  (5, 'web-design', 'Web Design', 'Design', 'Web design built to launch inside weeks, not quarters.', 'Every web design engagement we run ends in a live, indexable site — we''ve taken brands from a market stall to a fully digitized marketplace storefront in a 28-day delivery window, and we design every page with SEO and crawlability baked in from the wireframe stage, not bolted on after launch.', '["Full marketplace storefront design & build (Gaffar India, 28-day delivery)", "Responsive, SEO-structured page templates from day one", "Design systems reusable across a growing page catalog", "Direct handoff into our own Web Development track \\u2014 no design-to-dev drop-off"]', NULL, '[{"type": "case-study", "slug": "gaffar-india", "label": "Gaffar India \\u2014 full marketplace storefront"}]', '2026-09-24 16:37:20', '2026-09-24 16:37:20'),
  (6, 'mobile-app-designing', 'Mobile App Designing', 'Design', 'Mobile-first interfaces for the same products we design and ship end to end.', 'Our mobile app design work follows the same rule as everything else we design: it has to be buildable by our own engineering team, and it has to convert. We design mobile experiences for the client portals and dashboards behind products like Q Manager and Capital Keys, where a client checking project status or a lead reviewing a listing needs to complete the task in seconds, not minutes.', '["Mobile-first dashboard and portal UI (client-facing and internal)", "Component libraries shared between web and mobile builds for consistency", "Usability passes focused on task completion time, not just visual polish"]', NULL, '[{"type": "product", "slug": "q-manager", "label": "Q Manager \\u2014 client/team mobile-first portal"}]', '2026-09-24 16:37:20', '2026-09-24 16:37:20'),
  (7, 'landing-page-designing', 'Landing Page Designing', 'Design', 'Landing pages built around a single conversion event, tested until it wins.', 'A landing page from us is a hypothesis with a design attached. Trotr''s founder-storytelling travel funnel used this approach to hit 28x ROAS and ₹14L revenue on a single high-ticket offer — the page existed to test one narrative angle, and we iterated the layout until the numbers proved it out.', '["Trotr: founder-storytelling high-ticket funnel \\u2014 28x ROAS, \\u20b914L revenue", "Single-offer, single-CTA landing pages built for paid traffic", "On-page A/B test variants tied directly to ad creative hooks", "Server-side conversion tracking wired in from launch, not retrofitted"]', NULL, '[{"type": "case-study", "slug": "trotr-spain-pivot", "label": "Trotr: Spain Pivot \\u2014 28x ROAS funnel"}]', '2026-09-24 16:37:20', '2026-09-24 16:37:20'),
  (8, 'web-development', 'Web Development', 'Development', 'Next.js/React builds engineered for multi-vendor scale, not a template site.', 'We build the marketplaces, CRM portals, and proptech platforms our design and marketing work runs on — Next.js/React on the frontend, MySQL/Postgres and custom APIs underneath, built to hold up under real transaction volume and multi-vendor complexity, not just to demo well.', '["Multi-vendor marketplace engines (Gaffar India digital marketplace)", "Custom CRM/proptech web portals (Capital Keys, 64.7% conversion)", "High-performance MySQL/PostgreSQL-backed data layers with secure access controls", "Performance-tuned builds (SSR, code-splitting) engineered for Core Web Vitals"]', NULL, '[{"type": "case-study", "slug": "gaffar-india", "label": "Gaffar India \\u2014 multi-vendor marketplace engine"}, {"type": "case-study", "slug": "capital-keys", "label": "Capital Keys \\u2014 proptech CRM web portal"}]', '2026-09-24 16:37:20', '2026-09-24 16:37:20'),
  (9, 'mobile-app-development', 'Mobile App Development', 'Development', 'Mobile builds that share the same backend and design system as the web product.', 'Mobile development at Qala Labs isn''t a separate codebase bolted onto the web app after the fact — it''s built against the same API layer and design system as everything else we ship, so client portals and internal tools behave identically whether someone opens them on desktop or on their phone.', '["React Native / mobile-web hybrid builds sharing one backend", "Push notification and offline-state handling for field/on-the-go use", "App builds tied to the same CI/build pipeline as the web product"]', NULL, '[{"type": "product", "slug": "q-manager", "label": "Q Manager \\u2014 shared backend across web & mobile"}]', '2026-09-24 16:37:20', '2026-09-24 16:37:20'),
  (10, 'software-development', 'Software Development', 'Development', 'The same multi-agent, multi-tenant systems engineering we run our own products on.', 'This is the engineering discipline behind our own products: MarksOps'' LangGraph agent engine and FastAPI backend, and Q Manager, our internal Work OS unifying project management, shared client/team comms, and AI-assisted task creation across Admin/Team Lead/Team Member/Client roles. We build custom software the same way — role-scoped access, real data models, and zero-auto-execution safety rails on anything that touches money or client data.', '["Multi-agent backend architecture (LangGraph + FastAPI), the exact stack behind MarksOps", "Role-based multi-tenant systems (Admin / Team Lead / Team Member / Client scoping)", "Integration engineering: Odoo ERP, WhatsApp (Convertway), Unicommerce, Shiprocket, Tally Prime", "Safety-first automation: staged/draft writes with mandatory human approval on financial actions"]', NULL, '[{"type": "product", "slug": "marksops", "label": "MarksOps \\u2014 multi-agent backend platform"}, {"type": "product", "slug": "q-manager", "label": "Q Manager \\u2014 role-based multi-tenant Work OS"}]', '2026-09-24 16:37:20', '2026-09-24 16:37:20'),
  (11, 'digital-marketing', 'Performance Marketing', 'Marketing', 'Performance marketing measured in contribution margin, not impressions.', 'Every performance campaign we run is built around one number: contribution margin, not vanity reach. That discipline is what took Trotr to 28x ROAS on a single high-ticket funnel and Amazon Ads scaling to 11.2x ROAS with a 47% lower ACOS — real profit outcomes, tracked with server-side attribution so the numbers hold up under scrutiny.', '["Trotr: 28x ROAS, \\u20b914L revenue on a founder-led high-ticket funnel", "Amazon Ads scaling: 11.2x ROAS, 47% lower ACOS", "Nutrivend UK: 45 enterprise leads, 71% untapped market identified via B2B audience engineering", "D2C BNPL payment-architecture optimization: 15\\u201330% conversion uplift", "Server-side conversion tracking (Meta CAPI, GA4) so attribution survives iOS/ad-blocker signal loss"]', NULL, '[{"type": "case-study", "slug": "trotr-spain-pivot", "label": "Trotr: Spain Pivot \\u2014 28x ROAS"}, {"type": "case-study", "slug": "amazon-ads-scaling", "label": "Amazon Ads Scaling \\u2014 11.2x ROAS"}, {"type": "case-study", "slug": "nutrivend-uk", "label": "Nutrivend UK \\u2014 45 enterprise leads"}, {"type": "case-study", "slug": "d2c-bnpl-strategy", "label": "D2C BNPL Strategy \\u2014 conversion uplift"}]', '2026-09-24 16:37:20', '2026-09-24 16:37:20'),
  (12, 'search-engine-optimization', 'Search Engine Optimization', 'Marketing', 'SEO built for how people find you now — search engines, AI answer engines, and generative search alike.', 'We run SEO as three overlapping disciplines: classic technical/on-page SEO, AEO (answer-engine optimization for featured snippets and AI Overviews), and GEO (generative-engine optimization for how tools like ChatGPT and Perplexity cite you). Our Airborne Aviation Academy engagement was built and audited around exactly this stack — global areaServed schema, crawlability fixes, and structured content built to be quoted, not just ranked.', '["Technical SEO audits (Core Web Vitals, crawlability, structured data/schema)", "AEO: content structured to win featured snippets and AI Overview placements", "GEO: content and schema built to be cited correctly by AI answer engines", "Global areaServed and multi-region schema expansion (proven on Airborne Aviation Academy)"]', NULL, NULL, '2026-09-24 16:37:20', '2026-09-24 16:37:20'),
  (13, 'social-media-marketing', 'Social Media Marketing', 'Marketing', 'Community and creator programs that earn reach organically, and paid social that doesn''t waste it.', 'Some of our best social results cost nothing in ad spend — The Kashmiri Sound Movement label launch hit 3.4M+ organic views on zero paid budget. Where we do run paid social, like the CSK influencer/UGC program, we hold ourselves to the same bar: 5M+ reach and 12% engagement, not just impressions.', '["CSK influencer & UGC program: 5M+ reach, 12% engagement", "The Kashmiri Sound Movement: 3.4M+ organic views, zero ad spend", "Creator/UGC funnel design and management end to end", "Community loyalty and lifecycle programs layered on top of acquisition"]', NULL, '[{"type": "case-study", "slug": "kashmiri-sound-movement", "label": "The Kashmiri Sound Movement \\u2014 3.4M+ organic views"}]', '2026-09-24 16:37:20', '2026-09-24 16:37:20');
UNLOCK TABLES;

-- ------------------------------------------------------------
-- Table structure for `products`
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `products`;
CREATE TABLE `products` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `tagline` varchar(255) NOT NULL,
  `category` varchar(100) NOT NULL,
  `description` text NOT NULL,
  `features` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`features`)),
  `how_it_works` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`how_it_works`)),
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_prod_slug` (`slug`),
  KEY `idx_prod_category` (`category`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dumping data for `products` (4 records)
LOCK TABLES `products` WRITE;
INSERT INTO `products` (`id`, `slug`, `name`, `tagline`, `category`, `description`, `features`, `how_it_works`, `created_at`, `updated_at`) VALUES
  (1, 'marksops', 'MarksOps', 'Agentic Marketing, Sales, Ops & Finance — running as one system', 'AI Automation', 'MarksOps is Qala Labs'' own multi-agent operations platform: a LangGraph agent engine and FastAPI backend that unify Marketing, Sales, Operations, and Finance into a single native data layer instead of a stack of disconnected SaaS tools. On top of it runs a deployed ops-automation layer that reads real vendor emails, CRM leads, and marketplace listings and turns them into staged, human-approved actions — never silent auto-execution. Every financial write is a draft until a person approves it, every price alert is checked against a master catalog, and every lead gets a scored, 24-hour SLA-backed follow-up.', '[{"title": "Zero-auto-post finance ingestion", "description": "Parses Amazon VC, Meta/Google Ads, logistics, and SaaS invoices into draft bills in Odoo \\u2014 every entry stays in draft with a strict zero-auto-posting policy until a human approves it."}, {"title": "Marketplace price monitoring", "description": "Crawls Amazon and Flipkart listings twice daily, flags >5% deviations from your master price list, classifies root cause (own listing, seller, or competitor), and fires a WhatsApp alert."}, {"title": "Unicommerce inventory sync", "description": "Keeps stock levels reconciled across Amazon, Flipkart, Myntra, and your own storefronts, and flags discrepancies over 10 units straight to Operations."}, {"title": "Shiprocket logistics & NDR recovery", "description": "Tracks every shipment event end to end, auto-alerts on delays past the expected delivery date, and drives non-delivery-report recovery without manual chasing."}, {"title": "Payment reconciliation & Tally sync", "description": "Matches gateway settlements (Razorpay, Stripe, Cashfree, PayU) against expected net payouts down to the rupee, and mirrors approved vouchers into Tally over its XML gateway."}, {"title": "Omnichannel customer support agent", "description": "Classifies WhatsApp and email support intents, answers from order and return data, and escalates automatically on legal risk, high-value B2B tickets, or unresolved negative sentiment."}]', '[{"title": "Ingest", "description": "Emails, webhooks, and marketplace crawls feed structured events into the native FastAPI backend."}, {"title": "Reason", "description": "The LangGraph agent engine classifies, scores, and drafts the next action per domain (Marketing, Sales, Ops, Finance)."}, {"title": "Approve", "description": "Every financially or customer-facing action stages as a draft \\u2014 a human reviews and approves before it goes live."}, {"title": "Execute & alert", "description": "Approved actions post to Odoo, Tally, or the storefront, with WhatsApp alerts keeping the right team looped in."}]', '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (2, 'ai-recruiter', 'AI Recruiter', 'AI-run screening, cognitive interviews, and candidate synthesis', 'AI Hiring', 'AI Recruiter is Qala Labs'' end-to-end hiring platform, covering the full loop from job creation to offer. Recruiters build a role through a guided wizard that captures screening criteria and cognitive interview parameters up front, then candidates are evaluated through a live conversational AI interview and an embedded code or skills assessment. Every candidate profile resolves into an AI-generated synthesis — qualifications, strengths, growth areas, and a score breakdown — so recruiters spend their time on decisions, not first-pass reading.', '[{"title": "Guided job & screening wizard", "description": "A five-step flow \\u2014 role basics, requirements, cognitive screening questions, compensation, and publish \\u2014 turns a vacancy into a fully configured screening pipeline before it goes live."}, {"title": "Live AI interview panel", "description": "Candidates speak directly to a conversational AI interviewer that runs the cognitive screening questions set during job creation, no scheduling required for the first pass."}, {"title": "Embedded skills assessment", "description": "Role-specific challenges (e.g. a frontend engineering test) run inline in the candidate flow, scored alongside the interview for a single combined signal."}, {"title": "AI candidate synthesis", "description": "Every applicant resolves into a structured summary \\u2014 qualifications, strengths, growth areas, and a score breakdown \\u2014 instead of a raw resume dump."}, {"title": "Interviewer availability heatmap", "description": "A combined-availability calendar view lets recruiters set up final-round interviews across a team without the usual back-and-forth."}, {"title": "Full pipeline visibility", "description": "A recruiter dashboard tracks candidate counts, active roles, and stage progression across the whole hiring pipeline in one workspace."}]', '[{"title": "Define the role", "description": "Recruiters set requirements and cognitive screening criteria through the job-creation wizard."}, {"title": "Candidates apply", "description": "Applicants submit through a matched job listing and complete the AI interview and any embedded assessment."}, {"title": "AI synthesizes", "description": "Responses and assessment results resolve into a scored, structured candidate profile."}, {"title": "Recruiter decides", "description": "The team reviews synthesized profiles, schedules final interviews off the availability heatmap, and moves candidates to offer."}]', '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (3, 'ai-receptionist', 'AI Receptionist', 'A RAG-grounded voice agent that answers, qualifies, and books — 24/7', 'AI Voice', 'AI Receptionist is a voice agent built on real telephony infrastructure (TeleCMI, with Twilio fallback), not a chatbot with a phone number bolted on. Every call is transcribed, grounded against a Retrieval-Augmented Generation knowledge base of your own website and course content via vector search, and answered by a persona-driven conversational model tuned to your brand''s tone. Conversation history persists in Postgres rather than in-process memory, so the agent stays consistent across serverless instance recycles — a real operational detail, not a demo shortcut. Calls that show buying intent get scored, tagged, and pushed into the CRM with a WhatsApp booking confirmation, without a human ever picking up the phone.', '[{"title": "Real telephony, not a widget", "description": "Inbound and outbound calls run over TeleCMI SIP trunking with a Twilio fallback path \\u2014 this answers actual phone numbers, not just a website chat bubble."}, {"title": "RAG-grounded knowledge base", "description": "Every answer is retrieved via OpenAI embeddings against a vector store of your own site and course content, with a hard-coded fallback so the agent never goes silent."}, {"title": "Persona-driven conversation engine", "description": "A tuned system prompt gives the agent a consistent mentor voice and a consultative, non-pushy steering framework instead of a generic script."}, {"title": "Durable multi-turn memory", "description": "Conversation history is persisted in PostgreSQL per caller, so the dialogue stays coherent even when a serverless instance recycles mid-call \\u2014 a detail most voice-bot demos skip."}, {"title": "Lead scoring & CRM sync", "description": "Calls are classified Hot / Warm / Cold based on buying signals, synced straight to the CRM, and routed into the right nurture sequence automatically."}, {"title": "WhatsApp booking confirmation", "description": "When a caller agrees to a next step, the agent locks the slot and sends an instant WhatsApp confirmation \\u2014 no human handoff needed to close the loop."}]', '[{"title": "Call comes in", "description": "TeleCMI (or Twilio) routes the call to the assistant and streams the audio for transcription."}, {"title": "Retrieve context", "description": "The caller\\u2019s question is embedded and matched against your knowledge base via vector search."}, {"title": "Respond in voice", "description": "A grounded, persona-tuned response is generated and synthesized back to the caller in real time."}, {"title": "Qualify & book", "description": "Buying signals score the lead, sync it to the CRM, and \\u2014 on agreement \\u2014 lock a slot with a WhatsApp confirmation."}]', '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (4, 'q-manager', 'Q Manager', 'A Work OS that unifies projects, client comms, and AI-drafted replies', 'Agency Ops', 'Q Manager is the Work OS Qala Labs runs its own agency operations on — replacing the fragmented spread of a PM tool, a chat app, and email threads with one system scoped by role (Admin, Team Lead, Team Member, Client). Projects, tasks, time tracking, and a shared team-and-client comms layer sit on one data model, so "what is this client waiting on" and "who is overloaded this week" are one query, not five different tools cross-referenced by hand. An AI layer drafts replies and turns conversations into structured tasks, but strictly proposes — a human always approves before anything sends.', '[{"title": "Full project & task management", "description": "List, board, calendar, and Gantt views with subtasks, dependencies, custom statuses, and per-project custom fields \\u2014 ClickUp-Business-level parity, built for how Qala actually works."}, {"title": "Unified client comms timeline", "description": "Chat channels, task comments, and a connected email inbox interleave into one timeline per client or project \\u2014 nothing lives only in someone\\u2019s personal inbox."}, {"title": "AI draft replies & task extraction", "description": "AI proposes email/chat replies and turns long threads or client feedback into structured task proposals \\u2014 it never sends or creates without an explicit human approval click."}, {"title": "Role-scoped client portal", "description": "Clients get their own login to see project status, leave feedback, and message the team \\u2014 without visibility into internal notes, other clients, or team productivity data."}, {"title": "Client feedback with SLA tracking", "description": "Every feedback item (Bug, Change Request, Praise, Question) runs through a tracked lifecycle with time-to-acknowledge and time-to-resolve metrics and CSAT scoring."}, {"title": "Workload & capacity dashboards", "description": "Role-specific dashboards roll up utilization, throughput, and workload heatmaps \\u2014 Team Leads see their team, Admins see the company, without activity-monitoring creepiness."}]', '[{"title": "One workspace", "description": "Clients, projects, tasks, chat, and connected inboxes live in a single multi-tenant data model."}, {"title": "Work happens in view", "description": "Teams track tasks and time directly against client work; clients see status through their own scoped portal."}, {"title": "AI proposes", "description": "Long threads and feedback resolve into draft replies or structured task proposals for one-click creation."}, {"title": "A human approves", "description": "Every send, post, or record edit needs an explicit human confirmation \\u2014 AI never acts unsupervised."}]', '2026-09-24 16:37:21', '2026-09-24 16:37:21');
UNLOCK TABLES;

-- ------------------------------------------------------------
-- Table structure for `ai_agents`
-- ------------------------------------------------------------
DROP TABLE IF EXISTS `ai_agents`;
CREATE TABLE `ai_agents` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(255) NOT NULL,
  `name` varchar(255) NOT NULL,
  `tagline` varchar(255) NOT NULL,
  `what_it_does` text NOT NULL,
  `how_built` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`how_built`)),
  `integrations` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL CHECK (json_valid(`integrations`)),
  `created_at` timestamp NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_agent_slug` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dumping data for `ai_agents` (9 records)
LOCK TABLES `ai_agents` WRITE;
INSERT INTO `ai_agents` (`id`, `slug`, `name`, `tagline`, `what_it_does`, `how_built`, `integrations`, `created_at`, `updated_at`) VALUES
  (1, 'financial-reconciliation-agent', 'Financial Reconciliation Agent', 'Matches payment-gateway settlements against orders and bank feeds — automatically, safely.', 'Every day, money moves between payment gateways, bank accounts, and the order ledger — and small mismatches compound into real accounting drift if nobody catches them fast. This agent pulls settlement records from payment gateways, cross-references them against orders and bank statement lines, and surfaces every discrepancy the moment it appears. It never fixes the books itself — it hands a human a short, prioritized list of exactly what doesn''t match and why.', '["Part of the Marksops Agents platform (Module 6: payment_reconciliation), deployed on Google Cloud Run with FastAPI", "Pulls gateway settlement feeds and bank statement lines, joins them against the order ledger by transaction reference", "Flags amount/timing/reference mismatches as structured discrepancy records \\u2014 no silent auto-correction", "Runs on a recurring schedule via the orchestrator module (Cloud Scheduler), so reconciliation happens automatically without anyone remembering to run it"]', '["Payment gateway settlement feeds", "Bank statement ingestion", "Order ledger (core data layer)"]', '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (2, 'finance-bills-agent', 'Finance Bills Agent', 'Reads vendor emails, extracts the numbers, stages the entry — a human always approves the post.', 'Vendor invoices and ad-spend receipts arrive by email in wildly inconsistent formats — PDFs, HTML receipts, forwarded threads. This agent ingests those emails, extracts the real financial data (PO number, invoice number, GST breakdown, pre-tax/post-tax amounts), classifies the spend category, and stages a draft bill in the ERP. It is built around one hard invariant: it can never post that entry itself.', '["Marksops Agents Module 2 (finance_bills), FastAPI service with dedicated parsers per source: amazon_vc.py, ads_invoices.py, logistics_invoices.py, credit_card_alerts.py, saas_subscriptions.py", "A `detect_and_parse()` router auto-identifies the document type and extracts text from PDFs before routing to the right parser", "Classifies spend into [ADS, LOGISTICS, SAAS, VENDOR, UTILITY] and stages the record as `account.move` with move_type=''in_invoice'' and state=''draft'' in Odoo ERP", "Zero Auto-Posting Policy is enforced in code \\u2014 any call to action_post() is blocked and raises a ZeroAutoPostingViolationError", "Two entry points: POST /webhooks/gmail/incoming-bill (real-time push) and POST /tasks/daily-bill-sweep (Cloud Scheduler fallback at 8am IST), then a WhatsApp approval alert goes out via the Convertway client"]', '["Gmail (incoming invoices)", "Odoo ERP (draft staging)", "WhatsApp via Convertway (approval alerts)"]', '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (3, 'ai-voice-receptionist', 'AI Voice Agent / Receptionist', 'Answers, qualifies, and routes calls 24/7 — grounded in your own knowledge base.', 'This is a voice agent that actually answers the phone. It''s grounded via retrieval-augmented generation (RAG) against your real product docs, FAQs, and pricing — so it answers correctly the first time instead of guessing — and it qualifies the caller before deciding whether to book them, route them to a human, or just answer the question outright. Every call produces a transcript and a structured summary, so nothing said on the phone disappears.', '["Speech-to-text -> RAG retrieval over an indexed knowledge base -> LLM response -> text-to-speech pipeline", "Knowledge base built from real product documentation, FAQs, and pricing sheets, kept current so answers never go stale", "Call routing logic decides in real time: answer directly, book a follow-up, or escalate to a human line", "Every call logged as a transcript plus a structured summary (intent, outcome, next action) pushed into the CRM/lead pipeline"]', '["Telephony/voice pipeline", "RAG knowledge base", "CRM lead pipeline"]', '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (4, 'crm-leads-agent', 'CRM Leads Agent', 'Scores inbound leads and enforces a 24-hour SLA-backed follow-up loop — nothing goes cold.', 'Leads that don''t get a fast, relevant follow-up die quietly. This agent watches every inbound lead the moment it lands, scores it against a fit/intent model, and enforces a follow-up SLA — if a lead hasn''t been touched within 24 hours, it escalates. It''s the difference between a lead list and an actual pipeline.', '["Marksops Agents Module 7 (crm_leads), with a dedicated CRMLeadService handling scoring logic", "Webhook + scheduled-task router (router.py) ingests leads in real time and on a recurring sweep", "Mock-payload test harness (mocks.py) lets the scoring model be validated against realistic lead shapes before it touches production data", "SLA breaches trigger an alert through the same WhatsApp/Convertway channel used across the platform"]', '["CRM/lead intake webhooks", "WhatsApp via Convertway (SLA alerts)"]', '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (5, 'marketplace-crawler', 'Marketplace Crawler', 'Watches competitor and marketplace listings for price discrepancies — in real time.', 'Prices on marketplaces move constantly, and a single stale listing can quietly bleed margin for weeks before anyone notices. This agent continuously crawls marketplace and competitor listings, compares them against your master catalog, and flags discrepancies the moment they appear — so pricing decisions get made on current data, not last month''s screenshot.', '["Marksops Agents Module 3 (marketplace_crawler), FastAPI-hosted crawl + diff service", "Every observed price is checked against a master catalog record before an alert fires \\u2014 no false positives from untracked SKUs", "Runs as a scheduled sweep via the orchestrator module rather than a one-off script, so drift gets caught continuously"]', '["Marketplace listing feeds", "Master product catalog"]', '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (6, 'inventory-sync-agent', 'Inventory Sync Agent', 'Keeps stock levels consistent across every channel — so nothing oversells.', 'Selling the same SKU across multiple channels only works if stock numbers agree everywhere. This agent keeps inventory counts synchronized across channels in near-real time via Unicommerce, so a sale on one channel correctly decrements availability everywhere else before an oversell can happen.', '["Marksops Agents Module 4 (unicommerce_inventory), a dedicated multichannel inventory sync engine", "Reconciles stock deltas across connected sales channels through the Unicommerce integration layer", "Runs on the same Cloud Run + Cloud Scheduler orchestration pattern as the rest of the platform for consistent, automatic execution"]', '["Unicommerce", "Connected sales channels"]', '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (7, 'logistics-ndr-agent', 'Logistics & NDR Agent', 'Tracks every shipment end to end and resolves non-delivery reports automatically.', 'Once an order ships, the real risk is a non-delivery report (NDR) sitting unresolved while a customer waits. This agent tracks shipments post-purchase through to delivery, and when an NDR fires, it manages the resolution workflow (retry, reschedule, refund escalation) plus COD reconciliation — instead of that becoming a manual support ticket queue.', '["Marksops Agents Module 5 (shiprocket_logistics), integrated with the Shiprocket logistics API", "Tracks shipment state transitions end to end and reacts specifically to NDR events", "Handles COD reconciliation as part of the same workflow, closing the loop between logistics and finance"]', '["Shiprocket", "COD reconciliation ledger"]', '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (8, 'tally-connector-agent', 'Tally Connector Agent', 'Syncs approved financial entries into Tally Prime — natively, no manual re-entry.', 'Most ERP-to-Tally integrations mean someone re-typing numbers. This agent takes entries that have already been approved elsewhere in the platform (e.g. from the Finance Bills Agent) and syncs them into Tally Prime through a native XML connector, so the accounting system of record stays current without duplicate manual work.', '["Marksops Agents Module 8 (tally_connector), built around Tally Prime''s native XML API", "Consumes already-approved entries from upstream agents (e.g. finance_bills) rather than re-deriving data itself", "Keeps Tally as the accounting source of truth while every other agent in the platform stays advisory/staging-only"]', '["Tally Prime (XML API)", "Finance Bills Agent (upstream approved entries)"]', '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (9, 'customer-support-agent', 'Customer Support Agent', 'Handles omnichannel support conversations, and escalates only what a human genuinely needs to see.', 'Most support volume is repetitive — order status, return policy, shipping timelines. This agent handles that omnichannel (WhatsApp, email, chat) so your human support team only sees the conversations that actually need judgment, not the ones that need a lookup.', '["Marksops Agents Module 10 (customer_support), omnichannel agent built on the shared core/ infrastructure (structured logging, security tokens, MCP clients)", "Uses the same Convertway (WhatsApp) and Gmail MCP clients as the rest of the platform for a single conversation layer across channels", "Escalation logic routes only genuinely ambiguous or high-stakes conversations to a human \\u2014 resolved conversations close automatically"]', '["WhatsApp via Convertway", "Gmail", "Order/CRM data layer"]', '2026-09-24 16:37:21', '2026-09-24 16:37:21');
UNLOCK TABLES;

