LOCK TABLES `job_openings` WRITE;
INSERT INTO `job_openings` (`id`, `job_id`, `title`, `department`, `location`, `type`, `experience`, `compensation`, `tagline`, `description`, `responsibilities`, `requirements`, `tech_stack`, `active`, `created_at`, `updated_at`) VALUES
  (1, 'senior-ai-agent-architect', 'Senior AI Agent Architect & Systems Engineer', 'AI & Agents', 'Remote / London / Delhi NCR', 'Full-time', '4+ years in Python / TypeScript & LLM Systems', 'Competitive Base + Equity Tier', 'Design and deploy multi-agent coordination architectures for MarksOps and enterprise clients.', 'We are looking for a systems engineer who views LLMs not as simple chat endpoints, but as probabilistic reasoning kernels in complex event-driven state machines. You will build resilient autonomous agent swarms that coordinate CRM pipelines, ad creative generation, and operational reconciliation.', '["Architect robust multi-agent swarms with state machines, checkpointing, and vector memory systems.", "Build low-latency streaming backends with FastAPI, Node.js, and Redis.", "Deploy production-ready fine-tuned models, structured output extractors, and automated evaluation harnesses.", "Partner with client engineering leaders to embed Qala Labs agent infrastructure into existing enterprise CRMs and ERPs."]', '["Deep fluency with LangGraph, LlamaIndex, LiteLLM, or custom agent loop architectures.", "Proven experience shipping production Python and TypeScript applications with high reliability.", "Strong grasp of vector databases (pgvector, Qdrant), PostgreSQL performance, and asynchronous queues.", "Relentless curiosity about autonomous workflows and tool-calling reliability."]', '["Python", "TypeScript", "LangGraph", "FastAPI", "pgvector", "Redis", "Docker"]', 1, '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (2, 'lead-creative-technologist', 'Lead Creative Technologist & 3D WebGL Developer', 'Creative & Design', 'Remote / Hybrid (London / Delhi NCR)', 'Full-time', '3+ years in Three.js, WebGL & Modern React', 'Competitive Base + Creative Bonus', 'Craft interactive digital worlds that blur the line between software and cinema.', 'You are the rare bridge who can talk GLSL shaders, camera frustums, and physics simulation while having impeccable editorial taste in typography and spatial composition. You will lead our next-generation immersive web experiences for global brands.', '["Develop fluid, 60fps WebGL/Three.js interactive web graphics and volumetric visualizer components.", "Collaborate with brand directors to translate brand guidelines into kinetic, interactive digital systems.", "Optimize 3D models, texture budgets, and shader passes for instant loading on mobile and desktop devices.", "Pioneer the integration of real-time AI-generated assets into interactive 3D web canvases."]', '["Mastery of Three.js / React Three Fiber, GLSL shaders, and modern CSS/Tailwind.", "Deep appreciation for micro-interactions, spring physics, and Apple-grade polish.", "Strong portfolio demonstrating high-craft interactive web design or generative visual experiments.", "Familiarity with WebGPU and headless 3D asset optimization pipelines is a strong plus."]', '["Three.js", "React", "GLSL", "WebGL", "Tailwind CSS", "Vite", "Blender"]', 1, '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (3, 'staff-full-stack-engineer', 'Staff Full-Stack Engineer (React, Node, Cloud)', 'Engineering', 'Remote (UK / India / EMEA Timezones)', 'Full-time', '5+ years in Scaled Web Applications', 'Competitive Base + Performance Bonuses', 'Own the core web engine, data pipelines, and multi-tenant SaaS architectures.', 'We build high-performance web products, multi-vendor marketplace engines, and custom analytics backends. We need an experienced full-stack engineer who values rock-solid type safety, graceful offline fallbacks, and sub-100ms API response times.', '["Lead architecture and development of scalable React/Next.js and Node.js microservices.", "Ensure resilient client-side UX with optimistic mutations, error boundaries, and dual-target API fallbacks.", "Design modular database schemas (PostgreSQL / MySQL / Redis) with high data integrity.", "Mentor junior engineers and establish rigorous CI/CD, testing, and performance budgets."]', '["Expert-level TypeScript, React, and server-side runtimes (Node.js, edge workers).", "Track record of architecting resilient REST/GraphQL APIs and serverless backends.", "Obsession with performance metrics (Core Web Vitals, bundle tree-shaking, manual chunking).", "Clear, empathetic technical communication and pride in software craftsmanship."]', '["React", "TypeScript", "Node.js", "PostgreSQL", "Tailwind CSS", "Docker", "Vercel / Cloud Run"]', 1, '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (4, 'director-growth-performance', 'Director of Growth & Performance Architecture', 'Growth & Strategy', 'Remote / Dubai / London', 'Full-time', '5+ years scaling $1M+ paid media budgets', 'High Base + Performance Profit-Share', 'Engineer high-ticket conversion funnels, attribution architectures, and viral engines.', 'Forget vanity metrics. We engineer full-funnel customer acquisition systems for D2C market leaders and B2B disruptors. You will lead paid acquisition strategy across Meta, Google, TikTok, and Amazon, while partnering with our AI engineering team to automate ad creative variant testing.', '["Lead media strategy and ROAS optimization for top-tier international brands.", "Deploy server-side Conversions API (CAPI), multi-touch attribution, and predictive LTV models.", "Direct our creative team on high-converting ad angles, hook scripts, and UGC frameworks.", "Leverage AI generative tools to rapidly produce and test 100+ creative variations per sprint."]', '["Demonstrated history of scaling e-commerce or B2B accounts from 5-figure to 7-figure monthly budgets.", "Mastery of Meta Ads Manager, Google Ads (Search & PMax), TikTok Ads, and attribution tools (TripleWhale, Northbeam).", "Strong understanding of unit economics (CAC, LTV, payback period, blended ROAS).", "Exceptional analytical mindset paired with high creative intuition."]', '["Meta CAPI", "Google Ads", "TikTok Ads", "TripleWhale", "GA4", "SQL / BigQuery", "Figma"]', 1, '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (5, 'ai-prompt-creative-fellow', 'AI Prompt & Generative Media Fellow', 'Creative & Design', 'Remote', 'Fellowship', '1-3 years portfolio in Generative Media', 'Monthly Fellowship Grant + Project Bonuses', 'Push the bleeding edge of diffusion models, LoRA fine-tuning, and AI cinematic storytelling.', 'Are you the creator everyone asks "how did you generate that shot?" We are looking for an obsessive prompt engineer and generative artist to join our creative laboratory, producing mind-bending campaign visuals for global clients.', '["Generate ultra-high-fidelity imagery and video assets using Midjourney, Flux, ComfyUI, Runway, and Kling.", "Train bespoke LoRA weights and styling embeddings for client brand worlds.", "Collaborate with our video editors and 3D artists to compose hybrid generative-CGI motion spots.", "Document prompting workflows and build reusable node setups for internal creative tools."]', '["A jaw-dropping portfolio of AI-generated cinematic visuals or experimental motion design.", "Fluency with ComfyUI workflows, ControlNet, IP-Adapter, and prompt tuning.", "Keen eye for lighting, composition, lens focal lengths, and color theory.", "Ability to rapidly iterate based on client art direction."]', '["ComfyUI", "Flux", "Midjourney", "Runway Gen-3", "Photoshop", "Premiere / DaVinci"]', 1, '2026-09-24 16:37:21', '2026-09-24 16:37:21');
UNLOCK TABLES;

