INSERT INTO `creator_tracks` (`id`, `track_id`, `title`, `badge`, `description`, `deliverables`, `tools`, `ideal_for`, `created_at`, `updated_at`) VALUES
  (1, 'short-form-ugc', 'Short-Form Video & UGC Virtuosos', '100M+ VIEWS', 'Master the first 3 seconds. Create scroll-stopping TikToks, Instagram Reels, and YouTube Shorts for international D2C brands, sports franchises, and high-growth apps.', '["Authentic founder/creator style UGC videos", "High-velocity hook testing packs (5 hooks \\u00d7 2 bodies)", "Product unboxing & cinematic lifestyle showcases", "Viral reaction & storytelling formats"]', '["CapCut", "Premiere Pro", "DaVinci Resolve", "iPhone 15/16 Pro / Sony FX3"]', 'On-camera creators, lifestyle storytellers, and conversion-focused video directors.', '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (2, '3d-motion-cgi', '3D Motion & CGI Visualists', 'CINEMATIC POLISH', 'Push past flat design. Build physics-defying product reveals, futuristic industrial renderings, and hyper-realistic CGI mockups for luxury and tech brands.', '["Photorealistic 3D product animations & explodes", "Futuristic typography & motion graphic bumpers", "Real-time WebGL asset preparation for interactive sites", "Virtual production & visual effects compositing"]', '["Blender", "Cinema 4D", "Octane / Redshift", "After Effects", "Unreal Engine 5"]', '3D artists, motion designers, and industrial design visualizers.', '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (3, 'ai-prompt-cinema', 'AI Filmmakers & Prompt Architects', 'NEXT-GEN GENERATIVE', 'Pioneer AI cinematography. Blend diffusion models, custom LoRAs, and cinematic prompts to build hyper-creative visual worlds previously restricted to $500K Hollywood budgets.', '["Hyper-realistic AI cinematic commercial spots", "Custom visual worldbuilding & brand lookbooks", "Generative concept art & key visual exploration", "Hybrid AI + live-action motion integration"]', '["Midjourney v6", "Flux", "ComfyUI", "Runway Gen-3 Alpha", "Kling AI", "Luma Dream Machine"]', 'AI artists, concept visualizers, and experimental directors.', '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (4, 'creative-dev', 'Creative Technologists & Web Experimenters', 'CODE AS ART', 'Build generative web canvas experiences, interactive micro-sites, GLSL shader experiments, and dynamic product customizers that redefine the browser experience.', '["Interactive 3D landing page hero sections", "Custom Three.js particle systems and physics simulations", "Dynamic audio-reactive visualizers", "Generative SVG / CSS micro-animations"]', '["Three.js", "React Three Fiber", "GLSL", "Vite", "Tailwind", "WebGPU"]', 'Creative developers, frontend artists, and interactive web craftsmen.', '2026-09-24 16:37:21', '2026-09-24 16:37:21');
UNLOCK TABLES;

