-- Dumping data for `agency_models` (3 records)
LOCK TABLES `agency_models` WRITE;
INSERT INTO `agency_models` (`id`, `model_id`, `title`, `badge`, `headline`, `description`, `features`, `best_for`, `created_at`, `updated_at`) VALUES
  (1, 'white-label', 'White-Label AI & Engineering Infrastructure', '100% UNBRANDED BACKING', 'You own the client relationship. We power the deep tech.', 'Deliver complex autonomous AI agent swarms, bespoke 3D WebGL experiences, and high-scale full-stack platforms under your agency brand. We operate as your elite upstream engineering SWAT team.', '["Dedicated solution engineers attending scoping calls under your domain", "Custom instance deployment of MarksOps autonomous multi-agent pipelines", "Strict NDAs and unbranded repositories, documentation, and staging links", "Guaranteed enterprise SLAs with 24/7 technical on-call escalation"]', 'Boutique design studios, marketing agencies, and consultancies wanting to close $50k-$200k technical contracts without hiring 10 engineers.', '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (2, 'co-pitch', 'Enterprise Joint Ventures & Co-Pitching', 'WIN BIGGER TENDERS', 'Partner with Qala Labs to win enterprise RFPs that neither could take alone.', 'When your dream client requires both high-touch agency creative and deep enterprise AI/systems architecture, pitch together. Combine your brand resonance with Qala Labs deep tech pedigree.', '["Joint RFP response architecture and tailored technical proposal decks", "Direct pitch participation from Qala Labs technical founders and AI architects", "Transparent revenue split and unified project delivery governance", "Shared case study rights and co-branded industry thought leadership"]', 'Established agencies competing against monolithic consulting giants (Accenture, Publicis, Deloitte) for digital transformation projects.', '2026-09-24 16:37:21', '2026-09-24 16:37:21'),
  (3, 'referral-syndicate', 'Inbound Referral & Reciprocal Deal Flow', 'HIGH MARGIN REVENUE', 'Monetize leads outside your niche and receive qualified referrals.', 'Do clients ask you for custom AI agent swarms, complex marketplace architectures, or deep Three.js work that falls outside your core focus? Route them to Qala Labs and earn generous recurring retainers.', '["Up to 20% recurring referral commission on total project value or monthly retainers", "Reciprocal referral priority: We route branding, PR, and regional media requests back to our certified partner network", "Transparent deal tracking dashboard and immediate fee disbursements", "Zero operational overhead or delivery responsibility on your end"]', 'Agencies with high inbound deal flow looking to create a passive, high-margin revenue stream while serving their clients better.', '2026-09-24 16:37:21', '2026-09-24 16:37:21');
UNLOCK TABLES;

